# Method B · sources for V · building height (GHSL volume ÷ surface). Paths only: the factor node opens the files.
# GHSL rasters come from Discovery Catalog collections; each row of a collection is one raster file.
PRODUCTS = {'anbh': 'H_ANBH_E2018', 'agbh': 'H_AGBH_E2018', 'volume': 'V_E2020'}


def rasters(c):
    paths = dict(zip(c["product"], c["path"]))
    return {key: paths[product] for key, product in PRODUCTS.items()}


return {
    'sp_units_municipal': curio_dataset_path("imported.geosampa.sao-paulo-districts"),  # Discovery · GeoSampa · Distrito
    'chi_units_geojson': curio_dataset_path("imported.cityofchicago.community-areas"),  # Discovery · City of Chicago portal · Boundaries - Community Areas
    'ghsl_sp': rasters(curio_collection("imported.ghsl.sao-paulo-height-volume-rasters")),  # Discovery · local folder · GHSL rasters, São Paulo
    'ghsl_chi': rasters(curio_collection("imported.ghsl.chicago-height-volume-rasters")),  # Discovery · local folder · GHSL rasters, Chicago
}

